//! Made-up states for the context panel's snapshots (`--scene p3a-diff`, ...): each tab, each viewer,
//! the auto-open rules and the expanded panel. The files the viewers show are generated by
//! `samples.rs`; nothing here names anyone or anything real (the repository is public).

use std::rc::Rc;

use neko_protocol::workbench::TaskEvent;
use neko_protocol::{Artifact, ArtifactVersion};
use rune_kit::diff::DiffState;
use rune_kit::FileTree;

use crate::app::{App, DEMO_NOW};
use crate::panel::{Content, FilesMeta, Loaded, Opened, Shown, Tab, Target};
use crate::samples;
use crate::scenes::running;
use crate::work::{DiffLoad, diff_key};

const MIN: i64 = 60_000;
const SESSION: &str = "t6";

/// Three files changed, as the whole-task diff of the demo session.
const PATCH: &str = "diff --git a/web/src/board.tsx b/web/src/board.tsx\n--- a/web/src/board.tsx\n+++ b/web/src/board.tsx\n@@ -86,6 +86,10 @@ export function Board({ tasks }) {\n   const rows = tasks.map(Row);\n+  if (rows.length === 0) {\n+    return <p>No tasks yet.</p>;\n+  }\n   return <section>{rows}</section>;\n }\ndiff --git a/web/src/board.test.tsx b/web/src/board.test.tsx\n--- a/web/src/board.test.tsx\n+++ b/web/src/board.test.tsx\n@@ -1,3 +1,8 @@\n import { render } from \"./render\";\n+\n+test(\"an empty board says so\", () => {\n+  const out = render(<Board tasks={[]} />);\n+  expect(out.text()).toContain(\"No tasks yet.\");\n+});\ndiff --git a/web/src/empty.css b/web/src/empty.css\nnew file mode 100644\n--- /dev/null\n+++ b/web/src/empty.css\n@@ -0,0 +1,3 @@\n+.empty {\n+  color: var(--muted);\n+}\n";

/// What the folder of the demo session lists.
const FILES: &[&str] = &["Cargo.toml", "README.md", "web/src/board.tsx", "web/src/board.test.tsx", "web/src/empty.css", "web/src/index.tsx", "web/package.json", "crates/board/src/lib.rs", "crates/board/src/empty.rs", "crates/board/Cargo.toml", "docs/notes.md"];

fn session(s: &mut App) -> &mut crate::panel::SessionPanel {
    s.panel.sessions.entry(SESSION.to_owned()).or_default()
}

/// The demo session, built, with its three runs, its three commands and its folder.
fn base(s: &mut App) {
    running(s);
    let key = diff_key(SESSION, None);
    s.work.diffs.insert(key.clone(), DiffState::new(rune_kit::diff::parse(PATCH)));
    s.work.diff_load.insert(key, DiffLoad::Ready { truncated: false });
    s.panel.data_dir = std::path::PathBuf::from("/data/neko");
    session(s).person_closed = false;
    session(s).folder = Some(Some("/work/board".to_owned()));
    s.outbox.clear();
}

/// The folder's tree, with the files the diff changed marked.
fn tree(s: &mut App) {
    s.panel.files_tree = FileTree::new().build(FILES.iter().map(|f| (*f, false)));
    s.panel.files_meta = Some(FilesMeta { task_id: SESSION.into(), root: "/work/board".into(), truncated: false, count: FILES.len() });
    s.mark_changed_files();
}

fn record(id: &str, title: &str, kind: &str, versions: u32, ago_min: i64) -> Artifact {
    Artifact {
        id: id.into(),
        title: title.into(),
        kind: kind.into(),
        workspace_id: Some("w1".into()),
        message_id: None,
        versions: (1..=versions).map(|n| ArtifactVersion { n, file: format!("v{n}.{kind}"), at_ms: DEMO_NOW - ago_min * MIN - i64::from(versions - n) * 7 * MIN, note: String::new(), message_id: None }).collect(),
    }
}

/// Shows an artifact on the Canvas, loaded; two more sit in the list above it, not loaded.
fn show(s: &mut App, id: &str, title: &str, kind: &str, versions: u32, bytes: Vec<u8>) {
    base(s);
    let others = [("a-notes", "Release notes", "md", 2, 40), ("a-budget", "Budget", "csv", 1, 95)];
    for (oid, otitle, okind, v, ago) in others {
        s.panel.artifacts.insert(oid.into(), record(oid, otitle, okind, v, ago));
        session(s).shown.push(Shown { id: oid.into(), version: None, at_ms: DEMO_NOW - ago * MIN });
    }
    let art = record(id, title, kind, versions, 2);
    s.panel.artifacts.insert(id.into(), art);
    let sp = session(s);
    sp.shown.insert(0, Shown { id: id.into(), version: None, at_ms: DEMO_NOW - 2 * MIN });
    sp.canvas = Some(id.into());
    sp.tab = Some(Tab::Canvas);
    let loaded = Loaded::from_bytes(format!("/data/neko/artifacts/{id}/v{versions}.{kind}").into(), kind.into(), title.into(), bytes);
    s.panel.open = Some(Opened { target: Target::Artifact { id: id.into(), version: versions }, content: Content::Ready(Rc::new(loaded)) });
    s.layout.context.set_open(true);
}

fn state(s: &App, id: &str, version: u32, f: impl FnOnce(&mut crate::viewers::ViewerState)) {
    s.panel.states.with(&(id.to_owned(), version), f);
}

pub fn auto_canvas(s: &mut App) {
    base(s);
    s.panel.artifacts.insert("a-board".into(), record("a-board", "Board mockup", "png", 3, 2));
    session(s).shown.push(Shown { id: "a-board".into(), version: None, at_ms: DEMO_NOW - 2 * MIN });
    let loaded = Loaded::from_bytes("/data/neko/artifacts/a-board/v3.png".into(), "png".into(), "Board mockup".into(), samples::png(640, 400));
    s.panel.open = Some(Opened { target: Target::Artifact { id: "a-board".into(), version: 3 }, content: Content::Ready(Rc::new(loaded)) });
    s.layout.context.set_open(false);
    s.panel_on_select();
}

pub fn auto_diff(s: &mut App) {
    base(s);
    s.layout.context.set_open(false);
    s.panel_on_select();
}

pub fn auto_closed(s: &mut App) {
    super::scenes::live_for_pages(s);
    s.panel_on_select();
}

pub fn diff(s: &mut App) {
    base(s);
    s.panel_on_select();
}

pub fn files(s: &mut App) {
    base(s);
    tree(s);
    s.layout.context.set_open(true);
    session(s).tab = Some(Tab::Files);
}

pub fn file_open(s: &mut App) {
    files(s);
    session(s).file = Some("crates/board/src/lib.rs".into());
    let loaded = Loaded::from_bytes("/work/board/crates/board/src/lib.rs".into(), "rs".into(), "lib.rs".into(), samples::code().into_bytes());
    s.panel.open = Some(Opened { target: Target::File { task_id: SESSION.into(), path: "crates/board/src/lib.rs".into() }, content: Content::Ready(Rc::new(loaded)) });
}

pub fn terminal(s: &mut App) {
    base(s);
    s.layout.context.set_open(true);
    session(s).tab = Some(Tab::Terminal);
    // One command with colour and a rewritten progress line, to show the terminal does what a terminal does.
    let ansi = "   \u{1b}[32mCompiling\u{1b}[0m board v0.1.0\n\u{1b}[1m\u{1b}[33mwarning\u{1b}[0m: unused variable: `rows`\n   \u{1b}[34m-->\u{1b}[0m crates/board/src/lib.rs:12\nrunning 12 tests\n10%\r50%\r100%\ntest board::empty_state ... \u{1b}[32mok\u{1b}[0m\ntest board::sorted ... \u{1b}[31mFAILED\u{1b}[0m\n";
    if let Some(detail) = s.summary.as_mut().and_then(|m| m.detail.as_mut()) {
        detail.task.events.push(TaskEvent { at_ms: DEMO_NOW - MIN, role: "builder".into(), message: format!("VERIFICATION_COMMAND {}", serde_json::json!({"command": "cargo test -p board --color always", "output": ansi, "exit_code": 101})) });
    }
}

pub fn canvas_image(s: &mut App) {
    show(s, "a-board", "Board mockup", "png", 3, samples::png(640, 400));
}

pub fn image_gif(s: &mut App) {
    show(s, "a-loop", "Loading loop", "gif", 1, samples::gif(8));
}

pub fn image_svg(s: &mut App) {
    show(s, "a-logo", "Logo", "svg", 2, samples::svg());
}

pub fn markdown(s: &mut App) {
    show(s, "a-readme", "Changelog", "md", 2, samples::markdown().into_bytes());
}

pub fn code(s: &mut App) {
    show(s, "a-code", "word_count.rs", "rs", 1, samples::code().into_bytes());
}

/// A hundred thousand rows, scrolled to the middle.
pub fn table(s: &mut App) {
    show(s, "a-big", "Events", "csv", 1, samples::csv(100_000).into_bytes());
    s.panel.pending_scroll = Some("r50000".into());
}

/// Sixteen pages, on page 9.
pub fn pdf(s: &mut App) {
    show(s, "a-report", "Quarterly report", "pdf", 1, samples::pdf(16));
    state(s, "a-report", 1, |st| st.page = 8);
    s.panel.pending_scroll = Some("p8".into());
}

/// A knot in the wireframe, orbited a little.
pub fn model(s: &mut App) {
    show(s, "a-knot", "Torus knot", "glb", 1, samples::glb(160, 24));
    state(s, "a-knot", 1, |st| st.camera.wire = true);
}

pub fn model_solid(s: &mut App) {
    show(s, "a-knot", "Torus knot", "glb", 1, samples::glb(160, 24));
}

/// The spike's measuring model: 48,000 triangles, shaded.
pub fn model_48k(s: &mut App) {
    show(s, "a-knot", "Torus knot", "glb", 1, samples::glb(1000, 24));
}

pub fn web(s: &mut App) {
    show(s, "a-page", "Landing page", "html", 1, b"<html><body>hello</body></html>".to_vec());
}

pub fn fallback(s: &mut App) {
    show(s, "a-blob", "dump.bin", "bin", 1, vec![0, 159, 146, 150, 0, 1, 2, 3, 255, 254]);
}

pub fn too_large(s: &mut App) {
    files(s);
    session(s).file = Some("data/export.bin".into());
    s.panel.open = Some(Opened { target: Target::File { task_id: SESSION.into(), path: "data/export.bin".into() }, content: Content::TooLarge { size: 6_400_000, path: "/work/board/data/export.bin".into() } });
}

pub fn expanded(s: &mut App) {
    show(s, "a-report", "Quarterly report", "pdf", 1, samples::pdf(16));
    s.panel.expanded = true;
}
